values
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-356', 'A Constituicao Federal garante o direito a greve, que:', '["E absoluto, sem restricoes.","E exercido nos termos da lei, com as restricoes constitucionais.","E proibido em todos os casos.","E exclusivo dos servidores publicos.","E exclusivo dos trabalhadores privados."]'::jsonb, 1, 'O direito de greve e exercido nos termos da lei, com as restricoes constitucionais.', 'medium', 'Direito de greve', 'multiple_choice', 'published', 5425, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-357', 'A seguridade social, na Constituicao, abrange:', '["Apenas a previdencia.","Previdencia, assistencia social e saude.","Apenas a saude.","Apenas a assistencia social.","Apenas o SUS."]'::jsonb, 1, 'A seguridade social abrange previdencia, assistencia social e saude.', 'easy', 'Seguridade social', 'multiple_choice', 'published', 5426, 'FCC', 'Tribunais'),
