((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-363', 'A competencia privativa da Uniao inclui:', '["Saude e educacao.","Direito civil, comercial, penal, processual, eleitoral, agrario, maritimo, aeronautico, espacial e do trabalho.","Interesse local.","Tributos estaduais.","Tributos municipais."]'::jsonb, 1, 'A competencia privativa da Uniao inclui direito civil, comercial, penal, processual, eleitoral, agrario, maritimo, aeronautico, espacial e do trabalho.', 'medium', 'Competencias legislativas', 'multiple_choice', 'published', 5432, 'VUNESP', 'OAB'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-364', 'A competencia concorrente, em regra:', '["Apenas a Uniao pode legislar.","A Uniao legisla sobre normas gerais e os Estados sobre aspectos especificos.","Apenas os Estados podem legislar.","Apenas os Municipios podem legislar.","A Uniao e os Municipios legislam."]'::jsonb, 1, 'Na competencia concorrente, a Uniao legisla sobre normas gerais e os Estados sobre aspectos especificos.', 'medium', 'Competencias legislativas', 'multiple_choice', 'published', 5433, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-365', 'A Uniao pode intervir nos Estados para:', '["Garantir a lei federal, a ordem publica ou a execucao de ordem judicial, entre outros.","Apenas em caso de guerra.","Apenas por solicitacao do Governador.","Sem fundamento.","Apenas em eleicoes."]'::jsonb, 0, 'A Uniao pode intervir nos Estados para garantir a lei federal, a ordem publica ou a execucao de ordem judicial, entre outros.', 'medium', 'Intervencao federal', 'multiple_choice', 'published', 5434, 'FCC', 'Tribunais'),
