((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-366', 'A lei penal mais benéfica retroage para beneficiar o reu, conforme:', '["O principio da legalidade.","O principio da anterioridade.","O principio da retroatividade benéfica.","O principio da irretroatividade.","O principio da culpabilidade."]'::jsonb, 2, 'A lei penal mais benéfica retroage para beneficiar o reu.', 'medium', 'Lei penal no tempo', 'multiple_choice', 'published', 5435, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-367', 'A abolitio criminis ocorre quando:', '["A lei nova incrimina mais.","A lei nova deixa de considerar crime a conduta, retroagindo.","A lei nova aumenta a pena.","A lei nova e mais grave.","A lei nova e posterior."]'::jsonb, 1, 'A abolitio criminis ocorre quando a lei nova deixa de considerar crime a conduta, retroagindo.', 'medium', 'Lei penal no tempo', 'multiple_choice', 'published', 5436, 'VUNESP', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-368', 'O principio da consuncao ocorre quando:', '["Dois crimes sao punidos cumulativamente.","Um crime absorve outro, que se torna meio ou etapa de sua consumacao.","O agente desiste.","O crime e impossivel.","O agente e inimputavel."]'::jsonb, 1, 'O principio da consuncao ocorre quando um crime absorve outro.', 'medium', 'Principios penais', 'multiple_choice', 'published', 5437, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-369', 'A tentativa e punivel mesmo que:', '["O crime seja de acao penal privada.","O crime seja de acao penal publica.","O agente seja menor de 18 anos.","O agente seja inimputavel.","O crime seja impossivel."]'::jsonb, 1, 'A tentativa e punivel quando o crime e de acao penal publica, entre outros.', 'medium', 'Tentativa', 'multiple_choice', 'published', 5438, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-370', 'O concurso formal ocorre quando:', '["O agente comete crimes independentes.","O agente, com uma unica acao, pratica dois ou mais crimes.","O agente comete crime continuado.","O agente desiste.","O crime e impossivel."]'::jsonb, 1, 'O concurso formal ocorre quando o agente, com uma unica acao, pratica dois ou mais crimes.', 'medium', 'Concurso de crimes', 'multiple_choice', 'published', 5439, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-371', 'O concurso material ocorre quando:', '["O agente comete um unico crime.","O agente, mediante mais de uma acao, pratica dois ou mais crimes.","O agente desiste.","O crime e impossivel.","O agente e inimputavel."]'::jsonb, 1, 'O concurso material ocorre quando o agente, mediante mais de uma acao, pratica dois ou mais crimes.', 'medium', 'Concurso de crimes', 'multiple_choice', 'published', 5440, 'VUNESP', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-372', 'A legítima defesa de terceiro exige:', '["Agressao a terceiro e uso de meios moderados.","Agressao a si proprio.","Estado de necessidade.","Exercicio regular de direito.","Estrito cumprimento de dever legal."]'::jsonb, 0, 'A legítima defesa de terceiro exige agressao a terceiro e uso de meios moderados.', 'medium', 'Legitima defesa', 'multiple_choice', 'published', 5441, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-373', 'O estado de necessidade excludente de ilicitude exige:', '["Perigo a direito proprio e dever legal de enfrentar o perigo.","Perigo atual a direito proprio ou de terceiro, sem dever legal de enfrentar o perigo.","Agressao injusta.","Exercicio regular de direito.","Estrito cumprimento de dever legal."]'::jsonb, 1, 'O estado de necessidade exige perigo atual a direito proprio ou de terceiro, sem dever legal de enfrentar o perigo.', 'medium', 'Estado de necessidade', 'multiple_choice', 'published', 5442, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-374', 'O estrito cumprimento de dever legal exclui a ilicitude quando:', '["O agente age por conveniencia.","O agente cumpre dever imposto por lei.","O agente age por vontade propria.","O agente age por interesse.","O agente age por costume."]'::jsonb, 1, 'O estrito cumprimento de dever legal exclui a ilicitude quando o agente cumpre dever imposto por lei.', 'medium', 'Excludentes de ilicitude', 'multiple_choice', 'published', 5443, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-375', 'O exercicio regular de direito exclui a ilicitude quando:', '["O agente age de forma abusiva.","O agente exerce direito dentro dos limites legais.","O agente age por interesse.","O agente age por conveniencia.","O agente age por costume."]'::jsonb, 1, 'O exercicio regular de direito exclui a ilicitude quando o agente exerce direito dentro dos limites legais.', 'medium', 'Excludentes de ilicitude', 'multiple_choice', 'published', 5444, 'VUNESP', 'Carreiras policiais'),
